#!/bin/zsh
# loop-execute public review contract: rotating AR exchanges, verified fixes, one final post.
set -u
HERE="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(cd "$HERE/.." && pwd)"
source "$HERE/lib.sh"

SKILL="$(cat "$ROOT/.claude/skills/loop-execute/SKILL.md")"
FIX_SKILL="$(cat "$ROOT/.claude/skills/pr-review-fix-all/SKILL.md")"
FIX_AGENT="$(cat "$ROOT/.claude/agents/pr-review-fixer.md")"
PROTOCOL="$(cat "$ROOT/.claude/skills/loop-execute/references/loop-protocol.md")"

echo "review workflow: ledger-driven AR supervision"
assert_contains "$SKILL" '`[review: standard|max]`' "reads current review tiers"
assert_contains "$SKILL" 'Legacy tiers shallow and medium are rejected' "rejects legacy execution tiers"
assert_contains "$SKILL" '`LOOP_REVIEW_ROUNDS_DEFAULT` (2)' "shared outer-round default"
assert_contains "$SKILL" '`LOOP_REVIEW_INNER_DEFAULT` (2)' "shared inner-round default"
assert_contains "$SKILL" 'read §8 and the protocol from `RUNTIME_ROOT` at `REVIEW_READY`' "self-hosted supervision reloads merged instructions"
assert_contains "$SKILL" '`recover` → `next` → spawn → `record`' "supervisor drives the ledger"
assert_contains "$SKILL" 'loop-review.sh recover --ledger <F> --runs-dir <runs>' "recovers completed runs first"
assert_contains "$SKILL" 'loop-review.sh next --tier <T> --rounds <N> --inner <M> --ledger <F>' "selects one replay-derived run"
assert_contains "$SKILL" 'loop-review.sh prompt --role <R> --pr <url> --head <sha> --notes <file> --ledger <F> --run-dir <D>' "renders the frozen PR exchange"
assert_contains "$SKILL" 'loop-review.sh record --ledger <F> --run-dir <D> --stage <S> --role <R> --provider <P>' "records completion before advancing"
assert_contains "$SKILL" '`--chain <chain> --review-tier <T>' "passes chain + tier to every run"
assert_contains "$SKILL" '**never post or mutate GitHub**' "AR calls stay local"
assert_contains "$SKILL" 'Within a repository all R/C/T runs are sequential' "no parallel adversaries on one artifact"
assert_contains "$SKILL" 'Every R/C/T call is fresh' "prior exchange is inlined without session resume"
assert_contains "$SKILL" 'keep that SHA frozen throughout the inner loop' "round pins artifact head"
assert_contains "$SKILL" '`review-gpt|review-claude|review-grok`' "uses provider-slot chains"
assert_contains "$SKILL" 'never spawn a `disputed` runner' "CLI materializes cap disputes"
assert_contains "$SKILL" '`record` (or `recover`) exit 2' "invalid verdict also handled on recovery"
assert_contains "$SKILL" 're-run the same step once with a format reminder' "one format retry"
assert_contains "$SKILL" 'A second invalid verdict blocks that repository pipeline' "bounded retry follows HIL"
assert_contains "$SKILL" 'preserve the invalid output and retry-used evidence' "retry allowance survives crashes"
assert_contains "$SKILL" '`reviewPipeline = {phase, tier, rounds, inner, headSha, ledger}`' "persists replay inputs instead of stage cursor"
assert_contains "$SKILL" '- report: <absolute last R report.md of round r>' "fix gets one converged review"
assert_contains "$SKILL" '- disputed: <absolute current .disputed.md, if any>' "fix gets current disputed evidence"
assert_contains "$SKILL" 'last converged review + current disputed items' "final receives current evidence"
assert_contains "$SKILL" 'T `AGREE` skips remaining outer rounds' "confirmed clean round goes straight to final"
assert_contains "$SKILL" 'last R verdict is `NEEDS_CHANGES` or the round is disputed' "fix follows findings or dispute"
assert_eq "$([[ "$SKILL" == *'review-adv-'* || "$SKILL" == *'loop-review.sh stages'* || "$SKILL" == *'{phase, stage, tier, rounds}'* ]] && echo stale || echo current)" current "no static run list or stage cursor"
assert_contains "$PROTOCOL" 'Every round is local-only.' "all AR rounds stay off GitHub"
assert_contains "$SKILL" '`/pr-review-fix-all`' "loop workflow invokes remediation skill"
assert_contains "$PROTOCOL" '`/pr-review-fix-all`' "protocol invokes remediation skill"

echo "review protocol: rotating roles, persisted ledger, provider chains"
assert_contains "$PROTOCOL" '**Reviewer R**' "R owns the review and responses"
assert_contains "$PROTOCOL" '**Critic C**' "C audits the review against code"
assert_contains "$PROTOCOL" '**Third provider T**' "T confirms a candidate clean round"
assert_contains "$PROTOCOL" '"reviewPipeline": { "phase": 7, "tier": "standard", "rounds": 2, "inner": 2,' "state pins AR limits"
assert_contains "$PROTOCOL" '"ledger": "runs/review-p7-owner--api.ledger.tsv"' "state points to the repository ledger"
assert_contains "$PROTOCOL" 'CHAIN_REVIEW_STANDARD_GPT=("codex:@sol")' "standard GPT slot uses Sol"
assert_contains "$PROTOCOL" 'CHAIN_REVIEW_STANDARD_CLAUDE=("claude:opus")' "standard Claude slot uses Opus"
assert_contains "$PROTOCOL" 'CHAIN_REVIEW_STANDARD_GROK=("grok:default")' "standard Grok slot"
assert_contains "$PROTOCOL" 'CHAIN_REVIEW_MAX_GPT=("codex:@astra")' "max GPT slot uses Astra"
assert_contains "$PROTOCOL" 'CHAIN_REVIEW_MAX_CLAUDE=("claude:fable")' "max Claude slot uses Fable"
assert_contains "$PROTOCOL" 'EFFORT_REVIEW_MAX_GROK=max' "max Grok effort is clamped by the runner"
assert_contains "$PROTOCOL" 'LOOP_REVIEW_ROUNDS_DEFAULT=2' "two outer rounds by default"
assert_contains "$PROTOCOL" 'LOOP_REVIEW_INNER_DEFAULT=2' "two inner exchanges by default"

echo "review protocol: frozen AR exchange and ledger replay"
assert_contains "$PROTOCOL" '`[review: standard|max]`' "only current tiers are executable"
assert_contains "$PROTOCOL" 'Legacy tiers shallow and medium are rejected' "legacy tiers are hard errors"
assert_contains "$PROTOCOL" '| `standard` (default) | Sol `xhigh` | Opus `xhigh` | Grok `xhigh` | Opus `medium` | Opus `xhigh` |' "standard chain table"
assert_contains "$PROTOCOL" '| `max` | Astra `ultra` | Fable `max` | Grok `max` | Opus `medium` | Opus `max` |' "max chain table"
assert_contains "$PROTOCOL" 'R = P[(r−1) mod 3], C = P[r mod 3], T = P[(r+1) mod 3]' "provider rotation formula"
assert_contains "$PROTOCOL" '| 1 | gpt | claude | grok |' "round 1 rotation"
assert_contains "$PROTOCOL" '| 2 | claude | grok | gpt |' "round 2 rotation"
assert_contains "$PROTOCOL" '| 3 | grok | gpt | claude |' "round 3 rotation"
assert_contains "$PROTOCOL" '`F1`…`F10`' "findings have bounded stable IDs"
assert_contains "$PROTOCOL" '`APPROVE` or `NEEDS_CHANGES: <top issue>`' "R verdict grammar"
assert_contains "$PROTOCOL" '`AGREE`, `DISAGREE_EVIDENCE: <summary>`, or `DISAGREE_CONCERN: <summary>`' "C verdict grammar"
assert_contains "$PROTOCOL" 'A bare rebuttal is invalid.' "R must ground its response in code"
assert_contains "$PROTOCOL" 'appendix A.2.3/A.2.4 verbatim' "prompt source is vendored unchanged"
assert_contains "$PROTOCOL" 'Every R/C/T call is fresh; never resume a provider session.' "exchanges use fresh calls"
assert_contains "$PROTOCOL" 'R/C/T questions instead start a fresh call' "generic Q&A resume excludes AR calls"
assert_contains "$PROTOCOL" 'Runs within a round are sequential' "critic consumes the preceding review"
assert_contains "$PROTOCOL" 'capture its current head SHA' "round captures remote PR head"
assert_contains "$PROTOCOL" 'The artifact stays frozen throughout the inner loop' "no edits between R and C"
assert_contains "$PROTOCOL" 'first review is `APPROVE` and C answers `AGREE`' "initial clean result requires T"
assert_contains "$PROTOCOL" 'T `AGREE` skips every remaining outer round' "confirmed clean result stops early"
assert_contains "$PROTOCOL" 'No `skipped` ledger rows are written' "consumers infer skipped rounds"
assert_contains "$PROTOCOL" 'T becomes the critic for the rest of that inner loop' "veto changes the active critic"
assert_contains "$PROTOCOL" 'the opening `review` + `critic` is inner round 1' "inner count includes the opening pair"
assert_contains "$PROTOCOL" '`confirm` does not consume another inner round' "T audits the first pair within its inner count"
assert_contains "$PROTOCOL" '`ar_write_disputed`' "cap writes a synthetic disputed result"
assert_contains "$PROTOCOL" 'last R report and last critic report verbatim' "disputed artifact preserves both positions"
assert_contains "$PROTOCOL" 'including critic-added issues' "disputed findings cannot omit critic-only issues"
assert_contains "$PROTOCOL" '`disputed` > `findings` > `clean`' "dispute takes precedence"
assert_contains "$PROTOCOL" 'r < N, run `fix<r>` iff' "fixes only occur between outer rounds"
assert_contains "$PROTOCOL" 'last R verdict is `NEEDS_CHANGES` or' "fix rule follows the last reviewer"
assert_contains "$PROTOCOL" $'a<k>\tstage\trole\tprovider\tverdict\trun_dir' "ledger has six frozen columns"
assert_contains "$PROTOCOL" '`run_dir` is relative to the loop directory' "ledger paths are portable within the loop"
assert_contains "$PROTOCOL" '`disputed` | `DISPUTED` |' "synthetic dispute verdict"
assert_contains "$PROTOCOL" '`fix` | `PUSHED` or `NOOP` |' "verified remediation verdicts"
assert_contains "$PROTOCOL" '`final` | `REQUEST_CHANGES`, `COMMENT`, or `APPROVE` |' "final row records the actual GitHub event"
assert_contains "$PROTOCOL" 'loop-review.sh next --tier <T> --rounds <N> --inner <M> --ledger <F>' "next selects one ledger-derived run"
assert_contains "$PROTOCOL" 'loop-review.sh record --ledger <F> --run-dir <D> --stage <S> --role <R> --provider <P>' "record persists one completed run"
assert_contains "$PROTOCOL" 'loop-review.sh recover --ledger <F> --runs-dir <runs>' "recover replays completed run artifacts"
assert_contains "$PROTOCOL" 'loop-review.sh prompt --role <R> --pr <url> --head <sha> --notes <file> --ledger <F> --run-dir <D>' "prompt binds PR context and exchange"
assert_contains "$PROTOCOL" 'atomic (temporary file + rename), idempotent per `a<k>`' "record is crash-safe and idempotent"
assert_contains "$PROTOCOL" '`record` exit 2' "invalid verdict cannot advance the ledger"
assert_contains "$PROTOCOL" 're-run the same step once with a format reminder' "invalid verdict gets exactly one retry"
assert_contains "$PROTOCOL" 'second invalid verdict blocks that repository pipeline' "invalid verdict retry is bounded"
assert_contains "$PROTOCOL" '- report: <absolute last R report.md of round r>' "fix receives one converged review"
assert_contains "$PROTOCOL" '- disputed: <absolute current .disputed.md, if any>' "fix also verifies disputed evidence"
assert_contains "$PROTOCOL" '| `a9` | `final` | `final` | claude | `review-final` | `APPROVE` |' "example run list ends in one final review"
assert_contains "$PROTOCOL" '`reviewPipeline = {phase, tier, rounds, inner, headSha, ledger}`' "ledger replaces stage cursor"
assert_contains "$PROTOCOL" 'recover → GitHub final-marker reconcile → `next`' "recovery precedes next-step selection"
assert_contains "$PROTOCOL" 'never rerun a live pid, repeat a remediation push, or duplicate the final review' "crash-resume protects external effects"
assert_contains "$PROTOCOL" 'read §8 and this protocol from `RUNTIME_ROOT` at `REVIEW_READY`' "self-hosted review loads the merged contract"
assert_eq "$([[ "$PROTOCOL" == *'review-adv-'* || "$PROTOCOL" == *'loop-review.sh stages'* ]] && echo stale || echo current)" current "protocol has no old chains or run-list command"
assert_eq "$([[ "$PROTOCOL" == *'"stage": "round1"'* || "$PROTOCOL" == *'LOOP_REVIEW_ROUNDS_<TIER>'* ]] && echo stale || echo current)" current "protocol has no static cursor or per-tier defaults"

echo "review workflow: crash-resume replays evidence before scheduling"
assert_contains "$SKILL" '**Review resume**' "resume documents the AR pipeline"
assert_contains "$SKILL" 'recover → GitHub final-marker reconcile → `next`' "resume order protects external effects"
assert_contains "$SKILL" 'never rerun a live pid, repeat a remediation push, or duplicate the final review' "resume preserves completed work"
assert_contains "$SKILL" 'reconcile local and remote HEAD with the recorded starting/final SHAs' "partial push recovery uses git evidence"
assert_contains "$SKILL" 'recover its actual event/URL into the final run status and record idempotently' "recovers final post after process crash"
assert_contains "$SKILL" 'keep the persisted `headSha` within the inner loop' "resume never refreshes a frozen artifact"

echo "review workflow: remediation skill owns Opus delegation"
assert_eq "$([[ "$FIX_SKILL" == *'disable-model-invocation: true'* ]] && echo blocked || echo invocable)" "invocable" "headless fix runs can invoke the skill"
assert_contains "$FIX_SKILL" 'Write `RUN_DIR/remediation-plan.md`' "records reconciliation before fixes"
assert_contains "$FIX_SKILL" 'accepted, rejected, or duplicate' "disposes every finding"
assert_contains "$FIX_SKILL" 'maximum of 3 concurrent subagents' "bounds parallel remediation"
assert_contains "$FIX_SKILL" 'report:<path> [disputed:<path>] tier:<standard|max>' "single review plus optional disputed input"
assert_contains "$FIX_SKILL" 'Require exactly one `report:`' "rejects independent report sets"
assert_contains "$FIX_SKILL" 'last R `report.md`' "uses final reviewer position of current round"
assert_contains "$FIX_SKILL" 'including critic-added issues' "does not lose critic-only disputed concerns"
assert_contains "$FIX_SKILL" 'Verify every finding and every disputed item against the current code before accepting or rejecting it' "code verification precedes disposition"
assert_contains "$FIX_SKILL" 'Consensus or disagreement alone is not evidence' "does not treat convergence as correctness"
assert_contains "$FIX_SKILL" 'including an `APPROVE` report with critic-only disputed items' "dispute cannot become a false no-op"
assert_contains "$FIX_SKILL" 'Legacy tiers shallow and medium are rejected' "fix skill rejects legacy tiers"
assert_contains "$FIX_SKILL" '**standard / max — always spawn Opus fixers.**' "both tiers delegate accepted fixes to Opus"
assert_contains "$FIX_SKILL" '"result": "PUSHED | NOOP"' "records verified remediation result"
assert_contains "$FIX_SKILL" '"headBefore": "full starting SHA"' "records push recovery starting head"
assert_contains "$FIX_SKILL" '"headAfter": "full verified final SHA"' "records push recovery final head"
assert_eq "$([[ "$FIX_SKILL" == *'Sonnet'* || "$FIX_SKILL" == *'**shallow:**'* || "$FIX_SKILL" == *'three in medium/max'* ]] && echo stale || echo current)" current "no shallow coordinator path or report fan-in"
assert_eq "$([[ "$FIX_AGENT" == *'Astra/Fable reports'* ]] && echo stale || echo current)" current "fixer has no obsolete report assumptions"
assert_contains "$FIX_SKILL" '`model: opus` (the latest Opus)' "remediation subagents run the latest Opus"
assert_contains "$FIX_SKILL" 'Agent tool with the `pr-review-fixer` subagent' "spawns through the skill"
assert_contains "$FIX_AGENT" 'model: opus' "fixer agents run the latest Opus"
assert_contains "$FIX_AGENT" 'must not commit, push, or post to GitHub' "restricts fixer mutations"
assert_contains "$FIX_SKILL" 'overlapping files or dependencies serially' "serializes conflicting groups"
assert_contains "$FIX_SKILL" 'must not commit, push, or post to GitHub' "keeps mutations with coordinator"
assert_contains "$FIX_SKILL" 'Run the repository verification command' "coordinator verifies integrated fixes"
assert_contains "$FIX_SKILL" 'Commit logical fix groups and fast-forward push' "coordinator owns commits and push"

echo "review workflow: one severity-gated GitHub review"
assert_contains "$PROTOCOL" 'one or more `[blocker]` findings → `REQUEST_CHANGES`' "blockers request changes"
assert_contains "$PROTOCOL" 'one or more `[major]` findings → `COMMENT`' "majors produce comment review"
assert_contains "$PROTOCOL" 'otherwise → `APPROVE`' "clean major/blocker result approves"
assert_contains "$PROTOCOL" '<!-- loop-review:<runId>:p<N>:<owner--repo>:final -->' "final post is phase-idempotent"
assert_contains "$PROTOCOL" 'review-p<N>-<owner--repo>-a<k>' "review artifacts are phase-scoped"

echo "review workflow: milestones park at merge gates"
assert_contains "$SKILL" '**Milestones.**' "preflight validates milestone sections"
assert_contains "$SKILL" 'list that gate in `Depends on` **explicitly**' "preflight rejects a missing explicit gate dependency"
assert_contains "$SKILL" 'M≥2 branch names are checked by name only' "later milestones get no check/prepare at preflight"
assert_contains "$SKILL" 'set `state.milestone = 1`' "init starts at milestone 1"
assert_contains "$SKILL" 'milestone-1 participants only' "init prepares milestone-1 participants only"
assert_contains "$SKILL" 'schedules only phases of `state.milestone`' "SUB schedules only the current milestone"
assert_contains "$SKILL" 'one PR per milestone per participant' "PR per milestone per participant"
assert_contains "$SKILL" 'milestone'"'"'s `PR` bullet' "PR URL written to the milestone PR bullet"
assert_contains "$SKILL" 'On a `[gate: merge]` review, park instead of respawning' "gate review parks"
assert_contains "$SKILL" 'state.awaitingMerge {milestone, prs{slug:url}}' "parking persists awaitingMerge"
assert_contains "$SKILL" 'plan Status `awaiting merge`' "parking sets plan Status awaiting merge"
assert_contains "$SKILL" '`milestone.awaiting-merge`' "parking emits the typed event"
assert_contains "$SKILL" 'instruction to merge them and run `/loop-execute resume`' "parking notification names the resume command"
assert_contains "$SKILL" '**keep** `sub/REVIEW_READY`' "parking keeps REVIEW_READY"
assert_contains "$SKILL" 'never `finish`, never respawn' "parking neither finishes nor respawns"
assert_contains "$SKILL" 'does not respawn while `state.awaitingMerge` is set' "step 3b backstop skips respawn while parked"
assert_contains "$SKILL" 'writes `status.json{outcome:"blocked"}` and exits' "SUB seeing awaitingMerge blocks"
assert_contains "$PROTOCOL" '| `milestone.awaiting-merge` | supervise (loop-state.sh log) | detail = `M<n> owner/repo=<url> …` |' "event table: awaiting-merge"
assert_contains "$PROTOCOL" '| `milestone.resumed` | supervise (loop-state.sh log) | detail = `M<n>` |' "event table: resumed"
assert_contains "$PROTOCOL" '"awaitingMerge": { "milestone": 1, "prs": { "owner/api": "<gate PR url>" } }' "state schema: awaitingMerge"
assert_contains "$PROTOCOL" '"milestone": 1,' "state schema: milestone"
assert_contains "$PROTOCOL" '"milestones": { "1": { "prs": { "owner/api": "<gate PR url>" } } }' "state schema: milestone PR history"
assert_contains "$PROTOCOL" '`…/<owner--repo>/integration-<branch-slug>-<hash8>`' "worktree path for milestones >= 2"
assert_contains "$PROTOCOL" 'a parked loop keeps `sub/REVIEW_READY`' "two-tier: parked loop keeps REVIEW_READY"
assert_contains "$PROTOCOL" '| Milestone gate (supervise, after the gate review aggregates) |' "backend mapping: parking"
assert_contains "$PROTOCOL" 'Applies while `state.awaitingMerge` is set, whatever the plan or daemon status says.' "crash-resume: no respawn while parked"

echo "review workflow: milestone explainers never block the park or the resume"
assert_contains "$SKILL" '4. **Ship explainer (best-effort).**' "park runs the ship explainer"
assert_contains "$SKILL" 'A failed explainer never blocks the park.' "ship explainer failure never blocks the park"
assert_contains "$SKILL" 'explainer link (`--url`) or the explainer failure' "park notification carries the explainer link or failure"
assert_contains "$SKILL" '6. **Plan explainer (best-effort).**' "resume runs the plan explainer"
assert_contains "$SKILL" 'A failed explainer never stops the resume or the orchestrator.' "plan explainer failure never stops the resume"
assert_contains "$SKILL" 'A runner writes explainer
  props. Supervise only renders, publishes and links the page.' "supervise stays thin for explainers"
assert_contains "$PROTOCOL" '### Milestone explainers' "protocol documents milestone explainers"
assert_contains "$PROTOCOL" '`.loop/explainers/m<n>-ship/`' "ship output directory"
assert_contains "$PROTOCOL" '`.loop/explainers/m<N>-plan/`' "plan output directory"
assert_contains "$PROTOCOL" '--verify-cmd '"'"'node <RUNTIME_ROOT>/.claude/skills/visual-explainer/scripts/render.mjs --props <abs output dir>/props.json --check'"'"'' "explainer runner verifies its props"
assert_contains "$PROTOCOL" 'explainers/                # visual-explainer pages (never committed)' "layout lists explainers"
assert_contains "$PROTOCOL" '<!-- loop-explainer:m<n>-ship -->' "gate PR body marker"

echo "review workflow: the finish explains the last milestone, or the whole plan without milestones"
# The terminal-review finish block of step 8, with line wraps flattened to single spaces.
FINISH="${SKILL#*If this review is terminal}"
FINISH="${FINISH%%"### 9."*}"
FINISH="${(j: :)${=FINISH}}"
PROTOCOL_FLAT="${(j: :)${=PROTOCOL}}"
assert_contains "$FINISH" 'the final review of the last milestone of a plan' "finish path: last milestone of a plan with milestones"
assert_contains "$FINISH" 'the final review of a plan with no milestones' "finish path: plan with no milestones"
assert_contains "$FINISH" '2. **Ship explainer (best-effort).**' "finish runs the ship explainer"
assert_contains "$FINISH" 'For a plan with no milestones, this work is the whole plan.' "no-milestone finish explains the whole plan"
assert_contains "$FINISH" '`.loop/explainers/m<n>-ship/`' "finish ship output directory"
assert_contains "$FINISH" '`Explainer: <url> <!-- loop-explainer:m<n>-ship -->`' "finish links the page in each PR body"
assert_contains "$FINISH" 'A failed explainer never blocks the finish.' "ship explainer failure never blocks the finish"
assert_contains "$FINISH" 'the explainer link (`--url`) or the explainer failure' "completion notification carries the explainer link or failure"
assert_contains "$PROTOCOL" '| Finish step 2: after `loop-state.sh finish`, before the completion notification | `ship` | `.loop/explainers/m<n>-ship/` |' "protocol: finish row"
assert_contains "$PROTOCOL_FLAT" 'A plan with no milestones is milestone 1. Its finish `ship` page explains the whole plan.' "protocol: no-milestone plan gets a finish ship page"
assert_contains "$PROTOCOL_FLAT" 'At the park and at the finish, a `ship` link' "protocol: PR body link at the finish"

echo "review workflow: milestone resume after a merge"
assert_contains "$SKILL" '**Milestone resume**' "step 9 documents the milestone resume"
assert_contains "$SKILL" '`loop-milestone.sh check --state .loop/state.json`: exit 3 (open) → report each open' "open gate PR → report + stop"
assert_contains "$SKILL" 'exit 4 (closed unmerged) → open a HIL' "closed-unmerged gate PR → HIL"
assert_contains "$SKILL" 'exit 1 (gh/state error) → report it, stop' "gh error → report + stop"
assert_contains "$SKILL" '`loop-milestone.sh advance --state .loop/state.json --next <N>' "advance runs after a merged check"
assert_contains "$SKILL" 'Apply the printed patch with exactly one `loop-state.sh set`' "patch applied with a single set"
assert_contains "$SKILL" 'switch `RUNTIME_ROOT` to it' "self-hosted runtime root switches to the new worktree"
assert_contains "$SKILL" 'plan Status back to `in progress` + `loop-plan.sh push`' "resume repushes the plan as in progress"
assert_contains "$SKILL" 'remove
   `sub/REVIEW_READY`' "resume clears REVIEW_READY"
assert_contains "$SKILL" '`loop-state.sh log milestone.resumed`' "resume emits milestone.resumed"
assert_contains "$SKILL" 'respawn the
   orchestrator for the new milestone' "resume respawns the orchestrator"
assert_contains "$SKILL" 'rebuild `awaitingMerge {milestone, prs{slug:url}}`' "crash-resume recovers the park from a done gate review"
assert_contains "$PROTOCOL" 'permanently shipped: never re-check them' "merged milestones are never re-checked"
assert_contains "$PROTOCOL" 'recover `awaitingMerge` from the gate review' "protocol: recover awaitingMerge"
assert_contains "$PROTOCOL" '`loop-milestone.sh advance` interrupted' "protocol: interrupted advance re-runs idempotently"
assert_contains "$PROTOCOL" 'resume that advances the milestone switches `RUNTIME_ROOT`' "protocol: runtime root switch"
assert_contains "$SKILL" 'loop-state.sh set ". + $PATCH"' "patch applied as a top-level merge"
assert_contains "$SKILL" 'Never deep-merge with `*`' "patch never deep-merged"
assert_contains "$SKILL" 'Wait for every participating repository of this milestone.' "gate waits only on milestone participants"

echo "review workflow: milestone runtime root, park recovery, crash windows, final gate"
assert_contains "$SKILL" 'Record `state.runtimeRepo` + `state.runtimeRoot` only when the effort changes the Loop runtime' "init records runtime host only when self-hosted"
assert_contains "$PROTOCOL" '"runtimeRepo": null, "runtimeRoot": null,' "state schema: runtimeRepo + runtimeRoot"
assert_contains "$PROTOCOL" 'switches `RUNTIME_ROOT` to the patch'"'"'s `runtimeRoot` only when it is non-null' "protocol: switch runtime root only when self-hosted"
assert_contains "$PROTOCOL" 'a null `runtimeRoot` keeps the installed runtime' "protocol: null runtimeRoot keeps installed runtime"
assert_contains "$SKILL" 'patch `runtimeRoot` null (no host) → keep the installed runtime' "skill: null runtimeRoot keeps installed runtime"
assert_contains "$SKILL" 'persist it with `loop-state.sh set '"'"'.awaitingMerge = …'"'"'`' "recovered park is persisted before check"
assert_contains "$SKILL" 're-run step-8 park items 2-5 (idempotent)' "recovered park redoes Status/event/explainer/notify"
assert_contains "$SKILL" 'run resume step 5 only' "skill: crash after apply → restart only"
assert_contains "$PROTOCOL" '`state.resumePending` equals `state.milestone` (crash after the advance patch was applied, before restart)' "protocol: crash after apply keyed on resumePending"
print -r -- "$PROTOCOL" | grep -qF '`milestones[N].prs` recorded for the previous milestone, `awaitingMerge` null and `sub/REVIEW_READY` present'
assert_exit "$?" "1" "protocol: ambiguous crash-after-apply predicate gone"
assert_contains "$SKILL" '**Crash after apply:** `state.resumePending` equals `state.milestone`' "skill: crash after apply keyed on resumePending"
assert_contains "$SKILL" "loop-state.sh set '.resumePending = null'" "skill: restart clears resumePending last"
assert_contains "$PROTOCOL" 'run resume step 5 only (plan Status push, `milestone.resumed`, clear the marker, respawn)' "protocol: crash after apply → restart only"
assert_contains "$SKILL" 'park only when a later milestone exists' "final-milestone gate never parks"
assert_contains "$SKILL" '`[gate: merge]` on the final milestone → warn' "preflight warns on a final-milestone gate"

test_summary
